application.css:
* { box-sizing: border-box; }

:root {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #172033;
  background: #eef3f8;
  line-height: 1.5;
}

body { margin: 0; min-width: 0; }

.page-shell { width: min(1100px, 100%); margin: 0 auto; padding: 3rem 1.25rem; }
.page-header { margin-bottom: 2rem; }
.eyebrow { margin: 0 0 .35rem; color: #245b8f; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; font-size: .8rem; }
h1, h2 { line-height: 1.2; }
h1 { margin: 0 0 .65rem; font-size: clamp(2rem, 5vw, 3rem); }
h2 { margin: 0 0 1.35rem; font-size: 1.35rem; }
.page-header p:last-child { margin: 0; color: #46556a; }

.content-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr); gap: 1.5rem; align-items: start; }
.panel { background: #fff; border: 1px solid #d7e0ea; border-radius: .75rem; padding: clamp(1.25rem, 3vw, 2rem); box-shadow: 0 4px 14px rgb(25 52 77 / 7%); }
.form-group { margin-bottom: 1.1rem; }
.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
label { display: block; margin-bottom: .4rem; font-weight: 650; }
input, select { width: 100%; min-height: 2.75rem; padding: .55rem .7rem; border: 1px solid #9aaabd; border-radius: .4rem; background: #fff; color: #172033; font: inherit; }
input:focus, select:focus, button:focus { outline: 3px solid #8bc7ff; outline-offset: 2px; }
input:invalid:not(:focus):not(:placeholder-shown) { border-color: #b42318; }
button { border: 0; border-radius: .4rem; cursor: pointer; font: inherit; font-weight: 700; }
.primary-button { width: 100%; padding: .75rem 1rem; background: #145b8c; color: #fff; }
.primary-button:hover { background: #0d496f; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.section-heading h2 { margin-bottom: 1.35rem; }
.count { display: inline-grid; place-items: center; min-width: 2rem; height: 2rem; border-radius: 99px; background: #e3eef8; color: #164d76; font-weight: 700; }
.message { padding: .7rem .85rem; border-radius: .4rem; margin: 0 0 1rem; }
.success { background: #e3f5e9; color: #145c31; border: 1px solid #9fd4ae; }
.error { background: #fdebea; color: #8a1c13; border: 1px solid #e2aaa5; }
.booking-list { display: grid; gap: .85rem; }
.booking { border: 1px solid #cbd8e5; border-left: 4px solid #2575a8; border-radius: .45rem; padding: 1rem; }
.booking.cancelled { border-left-color: #727d89; opacity: .75; }
.booking-top { display: flex; justify-content: space-between; gap: 1rem; align-items: start; }
.booking h3 { margin: 0; font-size: 1.05rem; }
.booking p { margin: .35rem 0; color: #46556a; }
.booking .type { color: #172033; font-weight: 650; }
.cancel-button { padding: .45rem .7rem; background: #fff; color: #8a1c13; border: 1px solid #c77972; white-space: nowrap; }
.cancel-button:hover { background: #fff1f0; }
.empty-state { margin: 0; color: #59697b; }

@media (max-width: 700px) {
  .page-shell { padding: 2rem 1rem; }
  .content-grid { grid-template-columns: 1fr; }
}
@media (max-width: 420px) {
  .form-row { grid-template-columns: 1fr; gap: 0; }
  .booking-top { flex-direction: column; }
}

application.javascript:
const form = document.querySelector('#booking-form');
const dateInput = document.querySelector('[data-testid="booking-date"]');
const list = document.querySelector('[data-testid="booking-list"]');
const confirmation = document.querySelector('[data-testid="booking-confirmation"]');
const formError = document.querySelector('#form-error');
const count = document.querySelector('#booking-count');
const emptyState = document.querySelector('#empty-state');
let bookings = [];

function getToday() {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function formatBookingDate(date) {
  const parsed = new Date(`${date}T00:00:00`);
  return parsed.toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
}

function showError(message) {
  formError.textContent = message;
  formError.hidden = false;
}

function clearMessages() {
  formError.hidden = true;
  confirmation.hidden = true;
}

function readForm() {
  const data = new FormData(form);
  return {
    name: String(data.get('name') || '').trim(),
    email: String(data.get('email') || '').trim(),
    date: String(data.get('date') || ''),
    time: String(data.get('time') || ''),
    type: String(data.get('type') || '')
  };
}

function renderBookings() {
  list.querySelectorAll('[data-testid="booking"]').forEach((item) => item.remove());
  emptyState.hidden = bookings.length > 0;
  count.textContent = String(bookings.filter((booking) => !booking.cancelled).length);
  bookings.forEach((booking) => list.appendChild(createBookingElement(booking)));
}

function createBookingElement(booking) {
  const article = document.createElement('article');
  article.className = `booking${booking.cancelled ? ' cancelled' : ''}`;
  article.dataset.testid = 'booking';
  article.dataset.status = booking.cancelled ? 'cancelled' : 'active';

  const top = document.createElement('div');
  top.className = 'booking-top';
  const name = document.createElement('h3');
  name.dataset.testid = 'booking-name-display';
  name.textContent = booking.name;
  top.appendChild(name);

  if (!booking.cancelled) {
    const cancel = document.createElement('button');
    cancel.type = 'button';
    cancel.className = 'cancel-button';
    cancel.dataset.testid = 'booking-cancel';
    cancel.textContent = 'Cancel';
    cancel.addEventListener('click', () => cancelBooking(booking.id));
    top.appendChild(cancel);
  }
  article.appendChild(top);
  const details = document.createElement('p');
  details.textContent = `${formatBookingDate(booking.date)} at ${booking.time}`;
  article.appendChild(details);
  const type = document.createElement('p');
  type.className = 'type';
  type.textContent = booking.cancelled ? `${booking.type} — Cancelled` : booking.type;
  article.appendChild(type);
  const email = document.createElement('p');
  email.textContent = booking.email;
  article.appendChild(email);
  return article;
}

function cancelBooking(id) {
  const booking = bookings.find((item) => item.id === id);
  if (booking) {
    booking.cancelled = true;
    renderBookings();
  }
}

function handleSubmit(event) {
  event.preventDefault();
  clearMessages();
  if (!form.reportValidity()) return;
  const booking = readForm();
  if (booking.date < getToday()) {
    dateInput.setCustomValidity('Choose today or a future date.');
    dateInput.reportValidity();
    dateInput.setCustomValidity('');
    showError('The appointment date cannot be in the past.');
    return;
  }
  bookings.push({ ...booking, id: `${Date.now()}-${bookings.length}`, cancelled: false });
  renderBookings();
  confirmation.textContent = `Booking confirmed for ${booking.name}.`;
  confirmation.hidden = false;
  form.reset();
  dateInput.min = getToday();
}

dateInput.min = getToday();
form.addEventListener('submit', handleSubmit);
